using System;
using WoWProbe;
class QuickCorpseTests
{
    static int passed,failed;static void Check(bool b){if(!b)throw new Exception("Unexpected corpse behavior");}
    static FarmObservation O(){return new FarmObservation{Fresh=true,KnownCore=true,Health=100,TargetExists=true,TargetIdentityKnown=true,TargetToken=7,TargetDeadKnown=true,TargetDead=true,AttackabilityKnown=true,LootKnown=true,Lootable=true,LootEventsKnown=true,SkinKnown=true,Skinnable=true,SkinBindingKnown=true,SkinBindingCorrect=true,SkinSuccessKnown=true,CastEventsKnown=true,CastingKnown=true};}
    static void Test(string name,Action body){try{body();passed++;Console.WriteLine("PASS "+name);}catch(Exception ex){failed++;Console.WriteLine("FAIL "+name+": "+ex.Message);}}
    static int Main()
    {
        Test("remaining attackers interrupt even a new corpse immediately and no skin retry occurs in combat",()=>{var o=O();o.InCombat=true;var c=new QuickCorpse(7,true,o,0);for(int t=0;t<3000;t+=100){Check(c.Step(o,t,true).Action==QuickAction.None&&c.Interrupted&&!c.Done);}o.InCombat=false;c.Resume(o,3000);Check(c.Step(o,3499).Action==QuickAction.None);Check(c.Step(o,3500).Action==QuickAction.Loot);});
        Test("selected looted corpse skins with key seven without chat command",()=>{var o=O();var c=new QuickCorpse(7,true,o,0);Check(c.Step(o,500).Action==QuickAction.Loot);o.LootOpened=o.LootClosed=1;o.Lootable=false;var skin=c.Step(o,1200);Check(skin.Action==QuickAction.Skin&&skin.Key==55&&skin.SelectName==null&&QuickCombat.Matches(skin,o)&&!QuickCombat.MatchesChatCommand(skin,o));o.InCombat=true;Check(!QuickCombat.Matches(skin,o));});
        Test("combat immediately interrupts active looting or skinning even before attacker selection or health loss",()=>{for(int phase=0;phase<2;phase++){var o=O();if(phase==1)o.Lootable=false;var c=new QuickCorpse(7,true,o,0);Check(c.Step(o,500).Action==(phase==0?QuickAction.Loot:QuickAction.Skin));o.InCombat=true;Check(c.Step(o,501).Action==QuickAction.None&&c.Interrupted&&!c.Done);o.InCombat=false;c.Resume(o,600);Check(c.Step(o,1099).Action==QuickAction.None);Check(c.Step(o,1100).Action==(phase==0?QuickAction.Loot:QuickAction.Skin));}});
        Test("loot open and close precede one skin action and a dedicated success event",()=>{var o=O();var c=new QuickCorpse(7,true,o,0);Check(c.Step(o,500).Action==QuickAction.Loot);o.LootOpened=o.LootClosed=1;o.Lootable=false;Check(c.Step(o,1200).Action==QuickAction.Skin&&c.Loots==1);o.SkinSuccess=1;o.TargetExists=false;Check(c.Step(o,1500).Action==QuickAction.None&&!c.Done);c.Step(o,2800);Check(c.Done&&c.Skins==1);c.Step(o,3000);Check(c.Skins==1);});
        Test("lootability dropping before window events never races a skin key",()=>{var o=O();var c=new QuickCorpse(7,true,o,0);Check(c.Step(o,500).Action==QuickAction.Loot);o.Lootable=false;Check(c.Step(o,670).Action==QuickAction.None&&c.Skins==0);o.LootOpened=o.LootClosed=1;Check(c.Step(o,900).Action==QuickAction.None);Check(c.Step(o,1200).Action==QuickAction.Skin);});
        Test("lost corpse is reselected once and another dead token cannot authorize loot",()=>{var o=O();o.TargetExists=false;var c=new QuickCorpse(7,true,o,0);Check(c.Step(o,500).Action==QuickAction.CorpseSelect);o.TargetExists=true;o.TargetToken=8;Check(c.Step(o,1500).Action==QuickAction.None);c.Step(o,3600);Check(c.Done&&c.Loots==0&&c.Skins==0);});
        Test("stale data or player death cancels corpse actions",()=>{for(int i=0;i<2;i++){var o=O();var c=new QuickCorpse(7,true,o,0);if(i==0)o.Fresh=false;else o.PlayerDead=true;Check(c.Step(o,3100).Action==QuickAction.None&&c.Done&&c.Skins==0);}});
        Test("verified new attacker pauses corpse immediately without discarding it",()=>{var o=O();var c=new QuickCorpse(7,true,o,0);o.InCombat=true;o.TargetToken=8;o.TargetDead=false;o.TargetCanAttack=true;Check(c.Step(o,600).Action==QuickAction.None&&c.Interrupted&&!c.Done&&c.Loots==0&&c.Skins==0);});
        Test("recorded post kill combat lag retains the corpse until target reselect loot and skin",()=>{var o=O();var c=new QuickCorpse(7,true,o,0);o.InCombat=true;o.TargetExists=false;Check(c.Step(o,600).Action==QuickAction.None&&!c.Done&&!c.Interrupted);Check(c.Step(o,1400).Action==QuickAction.None&&!c.Done);o.InCombat=false;Check(c.Step(o,1200).Action==QuickAction.None);Check(c.Step(o,1699).Action==QuickAction.None);Check(c.Step(o,1700).Action==QuickAction.CorpseSelect);o.TargetExists=true;Check(c.Step(o,2300).Action==QuickAction.Loot);o.LootOpened=o.LootClosed=1;o.Lootable=false;Check(c.Step(o,3000).Action==QuickAction.Skin);o.SkinSuccess=1;c.Step(o,4600);Check(c.Done&&c.Loots==1&&c.Skins==1);});
        Test("health loss and prolonged combat yield while a transient flag alone does not",()=>{for(int i=0;i<2;i++){var o=O();var c=new QuickCorpse(7,true,o,0);o.InCombat=true;c.Step(o,600);if(i==0)o.Health=95;c.Step(o,i==0?700:3200);Check(c.Interrupted&&!c.Done);}});
        Test("unconfirmed loot times out without skinning or success credit",()=>{var o=O();var c=new QuickCorpse(7,true,o,0);Check(c.Step(o,500).Action==QuickAction.Loot);c.Step(o,5600);Check(c.Done&&c.Loots==0&&c.Skins==0);});
        Test("non skinnable unknown skin and wrong bindings do not emit skin keys",()=>{for(int i=0;i<3;i++){var o=O();o.Lootable=false;if(i==0)o.Skinnable=false;if(i==1)o.SkinKnown=false;if(i==2)o.SkinBindingCorrect=false;var c=new QuickCorpse(7,true,o,0);Check(c.Step(o,500).Action==QuickAction.None&&c.Done&&c.Skins==0);}});
        Test("failed skinning or elapsed cast deadline never becomes success",()=>{for(int i=0;i<2;i++){var o=O();o.Lootable=false;var c=new QuickCorpse(7,true,o,0);Check(c.Step(o,500).Action==QuickAction.Skin);if(i==0)o.CastFailed=1;c.Step(o,i==0?600:8600);Check(c.Done&&c.Skins==0);}});
        Test("cleared target after loot is reselected separately for optional skinning",()=>{var o=O();var c=new QuickCorpse(7,true,o,0);c.Step(o,500);o.LootOpened=o.LootClosed=1;o.TargetExists=false;Check(c.Step(o,1000).Action==QuickAction.CorpseSelect&&c.Loots==1);o.TargetExists=true;o.Lootable=false;Check(c.Step(o,1500).Action==QuickAction.Skin);});
        Test("failed last target selection retries the full name but only the original token may be looted",()=>{var o=O();o.TargetName="山猪";o.TargetExists=false;var c=new QuickCorpse(7,true,o,0);Check(c.Step(o,600).Action==QuickAction.CorpseSelect);var retry=c.Step(o,1700);Check(retry.Action==QuickAction.CorpseSelect&&retry.SelectName=="山猪");o.TargetExists=true;o.TargetToken=8;Check(c.Step(o,2000).Action==QuickAction.None&&c.Loots==0);o.TargetToken=7;Check(c.Step(o,2300).Action==QuickAction.Loot);});
        Console.WriteLine("Quick corpse tests: "+passed+" passed, "+failed+" failed. Simulated observations only.");return failed==0?0:1;
    }
}
